update public.homepage_versions set configuration_json = jsonb_set(configuration_json,'{sections}',(select jsonb_agg(case when s->>'id'='hero' then jsonb_set(s,'{settings,subheadline}',to_jsonb('We turn predictable monthly membership funding into reliable support for Mauritius''s most effective long-horizon social programs.'::text)) when s->>'id'='stats' then jsonb_set(jsonb_set(s,'{visible}','false'::jsonb),'{settings,metrics}','[{"id":"orgs","auto":true,"label":"Verified Organizations"},{"id":"initiatives","auto":true,"label":"Active Initiatives"},{"id":"memberships","auto":true,"label":"Active Memberships"},{"id":"profiles","auto":true,"label":"Impact Makers"}]'::jsonb) else s end order by ord) from jsonb_array_elements(configuration_json->'sections') with ordinality as x(s,ord) where s->>'id' not in ('urgent','trending','updates','newsletter'))) where id='89bbf5eb-c0e7-43a7-a317-9f51ae5ebb41';
